        :root{--ink:#f2fbff;--muted:#8ca4b4;--paper:#071523;--card:#0b1d2d;--cyan:#48dff0;--cyan2:#11b8ce;--line:#1c4354;--green:#42dba0;--amber:#f3bd3f;--red:#ff7186;--shadow:0 28px 85px rgba(0,0,0,.42)}
