<script>
document.addEventListener('DOMContentLoaded',()=>{const dialog=document.querySelector('[data-kla-beta-dialog]');if(!dialog)return;document.querySelector('[data-kla-beta-open]')?.addEventListener('click',()=>dialog.showModal());dialog.querySelector('[data-kla-beta-close]')?.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()})});
(() => {
    const price = document.querySelector('[data-kla-price]');
    const meta = document.querySelector('[data-kla-meta]');
    if (!price || !meta) return;
    const locale = @js(app()->getLocale() === 'en' ? 'en-US' : 'de-DE');
    const formatter = new Intl.NumberFormat(locale, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const refresh = async () => {
        try {
            const response = await fetch(@js(route('landing.kla.quote')), { headers: { Accept: 'application/json' }, cache: 'no-store' });
            if (!response.ok) return;
            const quote = await response.json();
            if (typeof quote.price !== 'number') return;
            price.textContent = `${formatter.format(quote.price)} ${quote.currency || 'USD'}`;
            meta.textContent = quote.realtime
                ? 'LIVE · TWELVE DATA'
                : (@js(app()->getLocale() === 'en' ? 'LAST PRICE · TWELVE DATA' : 'LETZTER KURS · TWELVE DATA'));
            meta.classList.toggle('quote-live', Boolean(quote.realtime));
        } catch (_) {}
    };
    refresh();
    window.setInterval(refresh, 30000);
})();
</script>
<script>
(() => {
    const carousel = document.querySelector('[data-terminal-carousel]');
    if (!carousel) return;
    const panels = [...carousel.querySelectorAll('[data-terminal-panel]')];
    const dots = [...carousel.querySelectorAll('[data-terminal-dot]')];
    const progress = carousel.querySelector('.terminal-progress');
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let active = 0, timer = null, paused = false;
    const restartProgress = () => {
        if (!progress || reduced) return;
        progress.classList.remove('is-running'); void progress.offsetWidth; progress.classList.add('is-running');
    };
    const show = index => {
        active = (index + panels.length) % panels.length;
        panels.forEach((panel, i) => panel.classList.toggle('is-active', i === active));
        dots.forEach((dot, i) => { dot.classList.toggle('is-active', i === active); dot.setAttribute('aria-current', i === active ? 'true' : 'false'); });
        restartProgress();
    };
    const schedule = () => { clearInterval(timer); if (!reduced) timer = setInterval(() => { if (!paused) show(active + 1); }, 7000); };
    dots.forEach(dot => dot.addEventListener('click', () => { show(Number(dot.dataset.terminalDot)); schedule(); }));
    carousel.addEventListener('mouseenter', () => { paused = true; }); carousel.addEventListener('mouseleave', () => { paused = false; });
    carousel.addEventListener('focusin', () => { paused = true; }); carousel.addEventListener('focusout', () => { paused = false; });
    schedule();
})();
</script>
